        // This code is vulnerable to Server-Side Request Forgery (SSRF)
        // because it directly uses user input to construct the URL without validation.
        String userInput = "http://example.com"; // In a real app, this comes from request parameter
        URL url = new URL(userInput); // Vulnerable: No protocol or host check

        // Attempting to fetch data from the constructed URL
        try (BufferedReader in = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = in.readLine()) != null) {
                System.out.println(line);
            }
        }
    }
}
