import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.URL;
import java.net.InetAddress;
import java.net.UnknownHostException;

public class SecureWebApp {
    public static void main(String[] args) throws Exception {
        String userInput = "http://example.com"; // User input from request parameter

        // Validate the URL before making the request
        URL url = new URL(userInput);

        // Check protocol is only HTTP or HTTPS
        String protocol = url.getProtocol();
        if (!protocol.equalsIgnoreCase("http") && !protocol.equalsIgnoreCase("https")) {
            throw new SecurityException("Invalid protocol");
        }

        // Check host is not a private or localhost address to prevent SSRF
        String host = url.getHost();
        InetAddress address = InetAddress.getByName(host);
        if (address.isLoopbackAddress() || address.isAnyLocalAddress() || address.isLinkLocalAddress()) {
            throw new SecurityException("Access to private/internal addresses is forbidden");
        }

        // Now safe to fetch data
        try (BufferedReader in = new BufferedReader(new InputStreamReader(url.openStream()))) {
            String line;
            while ((line = in.readLine()) != null) {
                System.out.println(line);
            }
        }
    }
}
